MOD = 10**9 + 7

def init_comb(n):
    C = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
    return C

def solve(n, s):
    C = init_comb(n)

    # 2 的幂
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = pow2[i-1] * 2 % MOD

    # 后缀奇数、偶数个数
    suf_odd = [0] * (n + 1)
    suf_even = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suf_odd[i] = suf_odd[i+1]
        suf_even[i] = suf_even[i+1]
        if int(s[i]) % 2 == 1:
            suf_odd[i] += 1
        else:
            suf_even[i] += 1

    ans = 0
    for i in range(n):
        # 单独的 '0'
        if s[i] == '0':
            ans = (ans + 1) % MOD
            continue

        # 以 s[i] 为首位的合法子序列总数
        total = pow2[n - i - 1]
        O = suf_odd[i + 1]
        E = suf_even[i + 1]

        # 平衡子序列数（奇偶相等）
        bad = 0
        if int(s[i]) % 2 == 1:      # 首字符奇数
            if E >= 1:
                bad = C[O + E][E - 1]
        else:                        # 首字符偶数
            if O >= 1:
                bad = C[O + E][O - 1]

        ans = (ans + total - bad) % MOD

    return ans

if __name__ == "__main__":
    n = int(sys.stdin.readline().strip())
    s = sys.stdin.readline().strip()
    print(solve(n, s))
